config.script:
// estoque_avisos — agente `script`. Comportamento = ESTE arquivo (DADO), nunca código de serviço.
//
// Agendado (padrão: dia útil às 8h, fuso da clínica — a clínica muda em "Quando roda"):
//   1. lista os alertas do estoque que a equipe ainda NÃO recebeu (listar_alertas);
//   2. guarda só os tipos ligados em `config.tipos`; sem nada, sai limpo;
//   3. manda UM resumo por papel de `config.papeis_destino` (ou para todos os conectados, com
//      `config.avisar_todos`): contagem por severidade/tipo + as primeiras linhas (produto, local,
//      lote/validade ou remessa/prazo, quantidade/mínimo). Os alertas não trazem dado de paciente;
//   4. SÓ se o aviso chegou a todos os destinos, marca as chaves como avisadas (marcar_avisados, até
//      500 por chamada). Aviso que falha NÃO marca: na próxima rodada o alerta volta.
//
// Falha visível: listar ou avisar que falha sai com log WARNING e `acao_bloqueada` no resumo.
// O resumo (result) só leva contagens e flags.
//
// Injetados: event, config, context, call() -> {ok,status_code,body}, log(), result().

var cfg = config || {};
var TIPOS = ['validade_vencida', 'validade_proxima', 'abaixo_minimo', 'consignado_prazo_vencido', 'consignado_prazo_proximo'];
var ROTULO = {
  validade_vencida: ['lote vencido', 'lotes vencidos'],
  validade_proxima: ['lote perto de vencer', 'lotes perto de vencer'],
  abaixo_minimo: ['item abaixo do mínimo', 'itens abaixo do mínimo'],
  consignado_prazo_vencido: ['remessa consignada com prazo vencido', 'remessas consignadas com prazo vencido'],
  consignado_prazo_proximo: ['remessa consignada perto do prazo', 'remessas consignadas perto do prazo']
};
var LOTE_MARCAR = 500;

function num(v, d) { return (v !== undefined && v !== null && v !== '' && !isNaN(Number(v))) ? Number(v) : d; }
function ligado(v) { return !(v === false || v === 'false' || v === 0 || v === '0'); }
function unwrap(r) {
  if (!r || !r.ok) return null;
  var b = r.body;
  return (b && b.data !== undefined) ? b.data : b;
}

// config.tipos: objeto {tipo: bool} (padrão do manifesto), lista de tipos ou texto "a,b". Ausente = todos.
function tiposLigados(t) {
  var on = {};
  var i;
  if (t === undefined || t === null || t === '') { for (i = 0; i < TIPOS.length; i++) on[TIPOS[i]] = true; return on; }
  if (typeof t === 'string') t = t.split(',');
  if (Array.isArray(t)) {
    for (i = 0; i < t.length; i++) { var k = String(t[i]).trim(); if (k) on[k] = true; }
    return on;
  }
  for (i = 0; i < TIPOS.length; i++) on[TIPOS[i]] = (t[TIPOS[i]] === undefined) ? true : ligado(t[TIPOS[i]]);
  return on;
}
// config.papeis_destino: "administrador,estoque" (o campo de papéis da Central) ou lista.
function papeisDe(v) {
  var lista = Array.isArray(v) ? v : String(v || '').split(',');
  var out = [];
  for (var i = 0; i < lista.length; i++) {
    var p = String(lista[i]).trim();
    if (p && out.indexOf(p) < 0) out.push(p);
  }
  return out;
}

function qtd(v) {
  var n = Number(v);
  if (v === null || v === undefined || isNaN(n)) return '?';
  return String(Math.round(n * 100) / 100).replace('.', ',');
}
function dataBr(iso) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  return m ? (m[3] + '/' + m[2] + '/' + m[1]) : '';
}
function quando(dias, verboFuturo, verboPassado) {
  if (dias === null || dias === undefined || isNaN(Number(dias))) return '';
  var d = Number(dias);
  if (d < 0) return verboPassado + ' há ' + (-d) + (d === -1 ? ' dia' : ' dias');
  if (d === 0) return verboFuturo + ' hoje';
  return verboFuturo + ' em ' + d + (d === 1 ? ' dia' : ' dias');
}
function corta(s, n) { s = String(s || ''); return s.length > n ? s.substring(0, n - 1) + '…' : s; }

function linha(a) {
  var t = a.tipo;
  var prod = a.produto_nome || 'Produto sem nome';
  var local = a.local_nome ? (' · ' + a.local_nome) : '';
  if (t === 'validade_vencida' || t === 'validade_proxima') {
    var lote = a.lote_numero ? (' · lote ' + a.lote_numero) : '';
    var val = dataBr(a.lote_validade);
    var q = quando(a.dias_restantes, 'vence', 'venceu');
    return (t === 'validade_vencida' ? 'Vencido: ' : 'Vence logo: ') + prod + local + lote +
      (val ? ' · validade ' + val : '') + (q ? ' (' + q + ')' : '') + ' · ' + qtd(a.quantidade) + ' no local';
  }
  if (t === 'abaixo_minimo') {
    return (a.severidade === 'critico' ? 'Sem saldo: ' : 'Abaixo do mínimo: ') + prod + local +
      ' · ' + qtd(a.quantidade) + ' de mínimo ' + qtd(a.minimo);
  }
  // consignado: a remessa tem vários itens, então não há produto
  var rem = 'Remessa' + (a.nf_numero ? ' NF ' + a.nf_numero : '') + (a.fornecedor_nome ? ' (' + a.fornecedor_nome + ')' : '');
  var prazo = dataBr(a.prazo_ate);
  var q2 = quando(a.dias_restantes, 'vence', 'venceu');
  return (t === 'consignado_prazo_vencido' ? 'Consignado vencido: ' : 'Consignado perto do prazo: ') + rem +
    (prazo ? ' · prazo ' + prazo : '') + (q2 ? ' (' + q2 + ')' : '') + ' · ' + qtd(a.quantidade) + ' em saldo';
}
function plural(n, par) { return n + ' ' + (n === 1 ? par[0] : par[1]); }

var on = tiposLigados(cfg.tipos);
var papeis = papeisDe(cfg.papeis_destino);
var avisarTodos = cfg.avisar_todos === true || cfg.avisar_todos === 'true';
var maxLinhas = Math.max(0, Math.min(num(cfg.max_linhas, 10), 30));
var link = cfg.link || '/financeiro/estoque';
var resumo = { alertas: 0, avisados: 0, marcados: 0, ignorados: 0, destinos: 0, falhas_aviso: 0 };

// ---- 1) alertas ainda não avisados ----
var r = call('listar_alertas', {});
var corpo = unwrap(r);
if (!corpo || !Array.isArray(corpo.itens)) {
  var http = (r && r.status_code) || null;
  log('estoque_avisos: FALHA ao listar os alertas (HTTP ' + (http || '?') + ')', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'listar_alertas'; resumo.http = http;
  if (r && r.ok) resumo.erro = 'formato_inesperado';
  result(resumo);
  return { ok: false, erro: 'listar_falhou', http: http };
}

// ---- 2) só os tipos ligados ----
var itens = [];
for (var i = 0; i < corpo.itens.length; i++) {
  var a = corpo.itens[i];
  if (a && a.chave && on[a.tipo]) itens.push(a);
}
// Contagem: `por_tipo` conta tudo, mesmo com a lista truncada (teto de 1000).
var conta = {};
var total = 0;
for (var t = 0; t < TIPOS.length; t++) {
  var tp = TIPOS[t];
  if (!on[tp]) continue;
  var n = (corpo.por_tipo && corpo.por_tipo[tp] !== undefined) ? num(corpo.por_tipo[tp], 0) : 0;
  if (!corpo.por_tipo) { n = 0; for (var j = 0; j < itens.length; j++) if (itens[j].tipo === tp) n++; }
  if (n) { conta[tp] = n; total += n; }
}
resumo.alertas = total;
resumo.na_lista = itens.length;
resumo.por_tipo = conta;
if (corpo.truncado) resumo.truncado = true;
if (!itens.length) {
  log('estoque_avisos: nenhum alerta novo');
  result(resumo);
  return { ok: true, alertas: 0 };
}

if (!avisarTodos && !papeis.length) {
  log('estoque_avisos: nenhum papel em papeis_destino — ninguém foi avisado', 'warning');
  resumo.acao_bloqueada = true; resumo.etapa = 'papeis_destino'; resumo.erro = 'sem_destino';
  result(resumo);
  return { ok: false, erro: 'sem_destino' };
}

// ---- 3) um resumo: críticos primeiro (a lista já vem na ordem: crítico, dias, produto) ----
var criticos = [], avisos = [];
var CRIT = { validade_vencida: 1, consignado_prazo_vencido: 1 };
for (var c = 0; c < TIPOS.length; c++) {
  var tc = TIPOS[c];
  if (!conta[tc]) continue;
  if (tc === 'abaixo_minimo') {
    var zerados = 0;
    for (var z = 0; z < itens.length; z++) if (itens[z].tipo === 'abaixo_minimo' && itens[z].severidade === 'critico') zerados++;
    if (zerados) criticos.push(plural(zerados, ['item sem saldo (com mínimo)', 'itens sem saldo (com mínimo)']));
    var resto = conta[tc] - zerados;
    if (resto > 0) avisos.push(plural(resto, ROTULO[tc]));
  } else if (CRIT[tc]) criticos.push(plural(conta[tc], ROTULO[tc]));
  else avisos.push(plural(conta[tc], ROTULO[tc]));
}
var partes = [];
if (criticos.length) partes.push('Urgente: ' + criticos.join(', ') + '.');
if (avisos.length) partes.push('Atenção: ' + avisos.join(', ') + '.');
var detalhe = [];
for (var d = 0; d < itens.length && d < maxLinhas; d++) detalhe.push('• ' + corta(linha(itens[d]), 160));
var faltam = total - detalhe.length;
if (detalhe.length && faltam > 0) detalhe.push('… e mais ' + faltam + ' no painel de alertas do estoque.');
var texto = partes.join('\n') + (detalhe.length ? '\n' + detalhe.join('\n') : '');
var titulo = 'Estoque: ' + (total === 1 ? '1 alerta novo' : total + ' alertas novos');
var message = {
  type: criticos.length ? 'urgent' : 'alert', title: titulo, text: texto, icon: 'warning',
  links: [{ url: link, text: 'Abrir o estoque' }],
  windowsalert: cfg.notificacao_do_sistema === false || cfg.notificacao_do_sistema === 'false'
    ? null : { text: titulo + ': ' + partes.join(' '), url: link }
};

var destinos = [];
if (avisarTodos) destinos.push({ acao: 'notificar', corpo: { type: 'mensagem', message: message } });
else for (var p = 0; p < papeis.length; p++) destinos.push({ acao: 'notificar_grupo', papel: papeis[p], corpo: { type: 'mensagem', group_id: papeis[p], message: message } });
resumo.destinos = destinos.length;
var falhou = [];
for (var k = 0; k < destinos.length; k++) {
  var rn = call(destinos[k].acao, destinos[k].corpo);
  if (rn && rn.ok) resumo.avisados++;
  else {
    falhou.push({ destino: destinos[k].papel || 'todos', http: (rn && rn.status_code) || null });
    log('estoque_avisos: FALHA ao avisar ' + (destinos[k].papel || 'todos') + ' (HTTP ' + ((rn && rn.status_code) || '?') + ')', 'warning');
  }
}
if (falhou.length) {
  // Não marca: na próxima rodada os alertas voltam e o aviso é tentado de novo.
  resumo.falhas_aviso = falhou.length;
  resumo.acao_bloqueada = true; resumo.etapa = 'notificar'; resumo.falhas_detalhe = falhou.slice(0, 10);
  result(resumo);
  return { ok: false, erro: 'aviso_falhou', alertas: total };
}

// ---- 4) marca o que foi avisado (só o que estava na lista; o resto volta na próxima rodada) ----
var chaves = [];
for (var q = 0; q < itens.length; q++) chaves.push(String(itens[q].chave));
for (var o = 0; o < chaves.length; o += LOTE_MARCAR) {
  var rm = call('marcar_avisados', { chaves: chaves.slice(o, o + LOTE_MARCAR) });
  var bm = unwrap(rm);
  if (!rm || !rm.ok || !bm) {
    log('estoque_avisos: FALHA ao marcar avisados (HTTP ' + ((rm && rm.status_code) || '?') + ') — pode repetir o aviso', 'warning');
    resumo.acao_bloqueada = true; resumo.etapa = 'marcar_avisados'; resumo.http = (rm && rm.status_code) || null;
    break;
  }
  resumo.marcados += num(bm.marcados, 0);
  resumo.ignorados += (bm.ignorados && bm.ignorados.length) || 0;
}
log('estoque_avisos: ' + total + ' alerta(s) avisado(s) a ' + destinos.length + ' destino(s), ' + resumo.marcados + ' marcado(s)',
  resumo.acao_bloqueada ? 'warning' : 'info');
result(resumo);
return { ok: !resumo.acao_bloqueada, alertas: total, marcados: resumo.marcados };
